interface Shape                       // abstraction
{
    public function area(): float;
}

abstract class BaseShape implements Shape
{
    public function __construct(private string $name) {}   // encapsulation

    public function describe(): string
    {
        return sprintf('%s with area %.2f', $this->name, $this->area());
    }
}

final class Circle extends BaseShape  // inheritance
{
    public function __construct(private float $radius) { parent::__construct('Circle'); }
    public function area(): float { return M_PI * $this->radius ** 2; }
}

final class Rectangle extends BaseShape
{
    public function __construct(private float $w, private float $h) { parent::__construct('Rectangle'); }
    public function area(): float { return $this->w * $this->h; }
}

foreach ([new Circle(2), new Rectangle(3, 4)] as $shape) {
    echo $shape->describe(), PHP_EOL;  // polymorphism
}

class Product
{
    public const TAX = 0.18;

    public function __construct(
        private string $name,
        private int $price,
    ) {}

    public function priceWithTax(): int
    {
        return (int) round($this->price * (1 + self::TAX));
    }
}

