abstract class Importer
{
    // Template method: the fixed algorithm
    final public function import(string $path): int
    {
        $rows = $this->read($path);
        $valid = array_filter($rows, [$this, 'isValid']);
        $this->store($valid);

        return count($valid);
    }

    abstract protected function read(string $path): array;   // children decide how

    protected function isValid(array $row): bool
    {
        return ! empty($row['email']);
    }

    private function store(array $rows): void { /* insert */ }
}

final class CsvImporter extends Importer
{
    protected function read(string $path): array { /* parse CSV */ return []; }
}

interface Clock
{
    public function now(): DateTimeImmutable;
}

final class SystemClock implements Clock
{
    public function now(): DateTimeImmutable { return new DateTimeImmutable(); }
}

final class FixedClock implements Clock    // for tests
{
    public function __construct(private DateTimeImmutable $at) {}
    public function now(): DateTimeImmutable { return $this->at; }
}

final class TrialPolicy
{
    public function __construct(private Clock $clock) {}

    public function hasExpired(DateTimeImmutable $startedAt): bool
    {
        return $startedAt->modify('+14 days') < $this->clock->now();
    }
}

$policy = new TrialPolicy(new FixedClock(new DateTimeImmutable('2025-06-20')));
var_dump($policy->hasExpired(new DateTimeImmutable('2025-06-01')));   // true

