interface Exporter { public function export(iterable $rows): string; }

final class CsvExporter implements Exporter  { public function export(iterable $rows): string { /* ... */ return ''; } }
final class JsonExporter implements Exporter { public function export(iterable $rows): string { return json_encode([...$rows]); } }

final class ExporterFactory
{
    public function make(string $format): Exporter
    {
        return match ($format) {
            'csv'  => new CsvExporter(),
            'json' => new JsonExporter(),
            default => throw new InvalidArgumentException("Unsupported format: {$format}"),
        };
    }
}

