interface DiscountStrategy
{
    public function apply(int $subtotal): int;
}

final class NoDiscount implements DiscountStrategy
{
    public function apply(int $subtotal): int { return $subtotal; }
}

final class PercentageDiscount implements DiscountStrategy
{
    public function __construct(private int $percent) {}
    public function apply(int $subtotal): int { return (int) round($subtotal * (100 - $this->percent) / 100); }
}

final class FixedDiscount implements DiscountStrategy
{
    public function __construct(private int $amount) {}
    public function apply(int $subtotal): int { return max(0, $subtotal - $this->amount); }
}

final class Cart
{
    public function __construct(private DiscountStrategy $discount = new NoDiscount()) {}

    public function total(int $subtotal): int
    {
        return $this->discount->apply($subtotal);
    }
}

echo (new Cart(new PercentageDiscount(10)))->total(2000);  // 1800
echo (new Cart(new FixedDiscount(250)))->total(2000);      // 1750

interface Listener
{
    public function handle(object $event): void;
}

final class EventBus
{
    /** @var array<class-string, Listener[]> */
    private array $listeners = [];

    public function listen(string $event, Listener $listener): void
    {
        $this->listeners[$event][] = $listener;
    }

    public function dispatch(object $event): void
    {
        foreach ($this->listeners[$event::class] ?? [] as $listener) {
            $listener->handle($event);
        }
    }
}

final class OrderPlaced { public function __construct(public int $orderId) {} }

final class SendConfirmation implements Listener
{
    public function handle(object $event): void { echo "Email for order {$event->orderId}\n"; }
}

$bus = new EventBus();
$bus->listen(OrderPlaced::class, new SendConfirmation());
$bus->dispatch(new OrderPlaced(15));   // Email for order 15
